        let t11 = (-xv[1]).mul_add(t3, t10);
            return Point { o: core::marker::PhantomData, c: gx::__private::reflect::<O, S, T, 3>(gx::slots::from_values::<S, T, 3>([t9, t11, T::from_i64(0)]), [false, false, false]) };
